        "task": "Campsite Reservations",
        "description": "Book well in advance (6+ months for popular parks/sites)."
      },
      {
        "task": "Park Entry Pass",
        "description": "Purchase annual pass or single-entry pass."
      },
      {
        "task": "Itinerary Planning",
